//! Bounded live registry lookup control; teardown is outside measurement.
// Rust guideline compliant 2026-02-21
use gpui_foreign_parent::{
    EditorHandle, EditorRegistry, OwnedEditorRegistry, ffi_boundary, no_thread_assertion,
};
use gpui_profiler::AllocSnapshot;
use std::{hint::black_box, rc::Rc, time::Instant};

fn cpu_ns() -> u64 {
    let mut time = libc::timespec {
        tv_sec: 0,
        tv_nsec: 0,
    };
    // SAFETY: time is aligned writable storage and the constant selects this process.
    let status = unsafe { libc::clock_gettime(libc::CLOCK_PROCESS_CPUTIME_ID, &raw mut time) };
    assert_eq!(status, 0);
    u64::try_from(time.tv_sec).unwrap() * 1_000_000_000 + u64::try_from(time.tv_nsec).unwrap()
}
fn measure(mut lookup: impl FnMut(usize) -> u64, live: usize, miss: bool) {
    const ITERATIONS: usize = 2_097_152; // Divisible by all tested registry sizes.
    for i in 0..4096 {
        black_box(lookup(black_box(i & (live - 1))));
    }
    let start_alloc = AllocSnapshot::now();
    let wall = Instant::now();
    let start_cpu = cpu_ns();
    let mut checksum = 0u64;
    for i in 0..ITERATIONS {
        checksum = checksum.wrapping_add(black_box(lookup(black_box(i & (live - 1)))));
    }
    let elapsed_cpu = cpu_ns() - start_cpu;
    let elapsed_wall = wall.elapsed().as_nanos();
    let allocations = AllocSnapshot::delta_since(start_alloc);
    let expected = if miss {
        0
    } else {
        (ITERATIONS as u64) * (live as u64 + 1) / 2
    };
    assert_eq!(checksum, expected);
    assert_eq!(allocations.count, 0);
    assert_eq!(allocations.bytes, 0);
    println!(
        "{{\"iterations\":{ITERATIONS},\"cpu_ns\":{elapsed_cpu},\"wall_ns\":{elapsed_wall},\"allocations\":{},\"allocated_bytes\":{},\"checksum\":{checksum}}}",
        allocations.count, allocations.bytes
    );
}
fn main() {
    let args: Vec<_> = std::env::args().collect();
    let live: usize = args[2].parse().unwrap();
    assert!(matches!(live, 1 | 64));
    let boundary = args[3] == "ffi";
    let miss = args[4] == "miss";
    match args[1].as_str() {
        "raw" => {
            let registry = EditorRegistry::new(no_thread_assertion);
            let keys: Vec<_> = (1..=live).collect();
            let owners: Vec<_> = (1..=live).map(|v| Rc::new(v as u64)).collect();
            for (key, owner) in owners.iter().enumerate() {
                // SAFETY: Rc allocations remain alive, correctly typed and on this
                // thread until all lookups finish and entries are unregistered.
                unsafe {
                    registry.register(keys[key], Rc::as_ptr(owner).cast());
                }
            }
            let lookup = |index| {
                registry
                    .with(&(if miss { usize::MAX } else { keys[index] }), |v: &u64| {
                        black_box(*v)
                    })
                    .unwrap_or(0)
            };
            if boundary {
                measure(|i| ffi_boundary(0, || lookup(i)), live, miss);
            } else {
                measure(lookup, live, miss);
            }
            for key in keys {
                registry.unregister(&key);
            }
            drop(owners);
        }
        "owned" => {
            let registry = OwnedEditorRegistry::new();
            let handles: Vec<_> = (1..=live)
                .map(|v| registry.insert(v as u64).unwrap())
                .collect();
            let invalid = EditorHandle::from_usize(usize::MAX).unwrap();
            let lookup = |index| {
                registry
                    .with(if miss { invalid } else { handles[index] }, |v| {
                        black_box(*v)
                    })
                    .unwrap_or(0)
            };
            if boundary {
                measure(|i| ffi_boundary(0, || lookup(i)), live, miss);
            } else {
                measure(lookup, live, miss);
            }
            registry.clear();
        }
        _ => panic!("invalid variant"),
    }
}

