from pathlib import Path
import subprocess,json,hashlib,statistics
out=Path('/Volumes/home_tmp/tmp/gpui-owned-editors-lookup.json')
build_records=json.loads(Path('/Volumes/home_tmp/tmp/gpui-owned-editors-probe-builds.json').read_text())
assert isinstance(build_records,list) and len(build_records)==2 and all(r['status']==0 for r in build_records)
records=[]; binaries={}
for instrumentation in ['cpu','alloc']:
 p=Path('/Volumes/home_tmp/tmp/gpui-owned-editors-probe-'+instrumentation+'/release/gpui-owned-editors-probe')
 binaries[instrumentation]={'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
 order=['raw','owned','owned','raw']*(3 if instrumentation=='cpu' else 1)
 for live in [1,64]:
  for boundary in ['direct','ffi']:
   for outcome in ['hit','miss']:
    for variant in order:
     c=[str(p),variant,str(live),boundary,outcome]
     r=subprocess.run(c,text=True,capture_output=True)
     assert r.returncode==0,(c,r.stderr)
     v=json.loads(r.stdout)
     assert v['allocations']==0 and v['allocated_bytes']==0
     records.append(dict(instrumentation=instrumentation,live=live,boundary=boundary,outcome=outcome,variant=variant,command=c,status=r.returncode,measurement=v))
source=Path('/Volumes/home_tmp/tmp/gpui-owned-editors-probe/src/main.rs')
manifest=source.parent.parent/'Cargo.toml';lock=manifest.with_name('Cargo.lock')
artifact=dict(build_checks=build_records,binaries=binaries,probe_source=source.read_text(),probe_sha256=hashlib.sha256(source.read_bytes()).hexdigest(),manifest=manifest.read_text(),lock=lock.read_text(),runner_source=Path(__file__).read_text(),samples=records,limitations=['Synthetic single-thread lookup; no native window callbacks, thread gating, rendering or energy measured.','CPU uses allocator-disabled binary; allocation counts use separate instrumented binary.','No task-owned builds or other benchmarks run during capture; thermal state and machine scheduling uncontrolled.','Setup, teardown and result validation are outside the measured interval. Clock calls are inside allocation interval.','Both variants load their keys from equally sized vectors; separately seeded standard HashMaps across subprocesses remain a source of variation.'])
assert isinstance(artifact['build_checks'],list) and all(r['status']==0 for r in artifact['build_checks'])
out.write_text(json.dumps(artifact,indent=2)+'\n')
for live in [1,64]:
 for boundary in ['direct','ffi']:
  for outcome in ['hit','miss']:
   med={v:statistics.median(r['measurement']['cpu_ns']/r['measurement']['iterations'] for r in records if r['instrumentation']=='cpu' and r['live']==live and r['boundary']==boundary and r['outcome']==outcome and r['variant']==v) for v in ['raw','owned']}
   print(live,boundary,outcome,med,'change_percent',round((med['owned']/med['raw']-1)*100,1),flush=True)
